// ── CF-17: PARSE TALLY PAYLOAD ────────────────────────────────────────────
const body   = $input.first().json.body;
const fields = body.data.fields;
const get    = (key) => fields.find(f => f.key === key)?.value ?? null;

// ── Zona horaria desde DROPDOWN ───────────────────────────────────────────
const tzField  = fields.find(f => f.key === 'question_MApRgX');
const tzId     = Array.isArray(tzField?.value) ? tzField.value[0] : null;
const tzOption = tzField?.options?.find(o => o.id === tzId);
const timezone = tzOption?.text ?? 'America/Mexico_City';

// ── Parsear horarios: "Lun-Vie 9:00-18:00, Sab 9:00-14:00" ──────────────
// Convierte a { mon:"9:00-18:00", tue:"9:00-18:00", ... } que CF-10 espera
const DAY_MAP = {
  'lun':'mon','mar':'tue','mie':'wed','mié':'wed','jue':'thu',
  'vie':'fri','sab':'sat','sáb':'sat','dom':'sun',
  'mon':'mon','tue':'tue','wed':'wed','thu':'thu',
  'fri':'fri','sat':'sat','sun':'sun'
};
const RANGE_MAP = {
  'lun-vie': ['mon','tue','wed','thu','fri'],
  'lun-sab': ['mon','tue','wed','thu','fri','sat'],
  'lun-sáb': ['mon','tue','wed','thu','fri','sat'],
  'lun-dom': ['mon','tue','wed','thu','fri','sat','sun'],
};

function parseHours(raw) {
  if (!raw) return {};
  const result = {};
  const segments = raw.split(',').map(s => s.trim()).filter(Boolean);
  for (const seg of segments) {
    // Formato: "Lun-Vie 9:00-18:00" o "Lun 9:00-14:00"
    const match = seg.match(/^([a-záéíóúüñ\-]+)\s+(\d{1,2}:\d{2}-\d{1,2}:\d{2})/i);
    if (!match) continue;
    const dayPart  = match[1].toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
    const hourPart = match[2];
    const expanded = RANGE_MAP[dayPart];
    if (expanded) {
      expanded.forEach(d => { result[d] = hourPart; });
    } else {
      const key = DAY_MAP[dayPart];
      if (key) result[key] = hourPart;
    }
  }
  return result;
}

// ── Parsear servicios: "Nombre/precio/minutos" uno por línea ─────────────
const servicesRaw = get('question_J2vzgd') ?? '';
const services = servicesRaw
  .split('\n')
  .map(l => l.trim())
  .filter(l => l.length > 0)
  .map(l => {
    const p = l.split('/');
    return {
      name:             (p[0] ?? '').trim(),
      price:            parseFloat((p[1] ?? '0').replace(/[^0-9.]/g,'')) || 0,
      duration_minutes: parseInt((p[2] ?? '30').trim(), 10) || 30,
      is_active:        true
    };
  })
  .filter(s => s.name.length > 0);

// ── Normalizar número WhatsApp (quitar + y espacios) ─────────────────────
const adminWa = (get('question_vN5YgQ') ?? '').replace(/[\s\+\-]/g, '');

// ── Payload estructurado ──────────────────────────────────────────────────
return [{ json: {
  clinic_name:            get('question_BGW76N'),
  doctor_name:            get('question_kYBEgM'),
  admin_wa:               adminWa,
  email:                  get('question_KMK1O7'),
  timezone:               timezone,
  business_address:       get('question_LdLpg1'),
  google_maps_url:        get('question_pLpOMb'),
  working_hours_raw:      get('question_1roVxW'),
  working_hours_json:     parseHours(get('question_1roVxW')),
  welcome_message:        get('question_g56Gpd'),
  about_text:             get('question_yl5YG4'),
  cancellation_policy:    get('question_XeP0g4'),
  booking_buffer_minutes: parseInt(get('question_8d4xWx') ?? '0', 10) || 0,
  calcom_event_type_id:   get('question_0EROl6'),
  calendar_id:            get('question_zK5YOq'),
  notes:                  get('question_5dPxQd'),
  services:               services,
  tally_form_id:          body.data.formId,
  tally_submission:       body.data.submissionId,
  created_at:             body.data.createdAt,
}}];

// Recuperar tenant_id del INSERT
const parsed   = $('Parse Tally Fields').item.json;
const raw      = $input.first().json;
const tenant   = Array.isArray(raw) ? raw[0] : raw;

return [{ json: { ...parsed, tenant_id: tenant.id, _tenant: tenant } }];

// Expandir servicios — uno por item para el Loop
const e        = $input.first().json;
const services = e.services ?? [];

return services.map(s => ({
  json: {
    tenant_id:        e.tenant_id,
    name:             s.name,
    price:            s.price,
    duration_minutes: s.duration_minutes,
    is_active:        true
  }
}));

const items = $input.all();
const first = $('Recover after settings').item.json;
const svcCount = items.filter(i => i.json?.tenant_id && i.json?.name).length;

return [{ json: {
  status:           'onboarding_complete',
  tenant_id:        first.tenant_id,
  clinic_name:      first.clinic_name,
  doctor_name:      first.doctor_name,
  admin_wa:         first.admin_wa,
  timezone:         first.timezone,
  calcom_event_id:  first.calcom_event_type_id ?? null,
  services_created: svcCount,
  working_hours:    first.working_hours_json ?? {},
  pending_steps: [
    'Asignar evo_instance_name en tabla tenants',
    'Conectar WhatsApp Business en Evolution API',
    first.calcom_event_type_id ? null : 'Configurar Cal.com Event Type ID',
  ].filter(Boolean),
  note: 'Tenant creado correctamente. Ver pending_steps para completar la configuración.',
}}];

// Construir mensaje de bienvenida para el admin de la clínica
const e = $input.first().json;
const pending = (e.pending_steps ?? []).map(s => `• ${s}`).join('\n');
const body =
  `✅ *¡Clínica registrada exitosamente!*\n\n` +
  `🏥 *${e.clinic_name}*\n` +
  `👨‍⚕️ ${e.doctor_name}\n\n` +
  `Se crearon *${e.services_created}* servicio(s).\n\n` +
  (pending ? `📋 *Pasos pendientes:*\n${pending}\n\n` : '') +
  `Tu ID de clínica: \`${e.tenant_id}\`\n\n` +
  `_ClinicFlow — Sistema de citas automatizado_`;

return [{
  json: {
    ...e,
    _outbound_admin: {
      wa_number: e.admin_wa,
      body:      body
    }
  }
}];
